cd "C:/visual projects/game" && python - <<'EOF'
p='view/style_showcase.gd'
s=open(p,encoding='utf-8').read()
s=s.replace('const SAND_CLAY := Color("a97e5a")\n','const SAND_CLAY := Color("9a7a68")\nconst SAND_WET := Color("8f95a8")  # мокрый песок: холодный сдвиг в лиловый (art_style §1.5, тень уходит в синий)\nconst SAND_POOL := Color("5d9aa0")  # лужи отлива: выцветший бирюзовый\nconst POOL_EDGE := 0.34  # порог шума: мокрое пятно\nconst POOL_CORE := 0.52  # порог шума: лужа\n')
s=s.replace('''	var img := Image.create(SAND_TEXELS, SAND_TEXELS, false, Image.FORMAT_RGB8)
	for y in SAND_TEXELS:
		for x in SAND_TEXELS:
			var v := n.get_noise_2d(x, y) * 0.7 + n2.get_noise_2d(x, y) * 0.3
			var c := SAND.lerp(SAND_SALT if v > 0.0 else SAND_CLAY, clampf(absf(v) * 1.6, 0.0, 0.75))
''','''	var n3 := FastNoiseLite.new()
	n3.seed = 23
	n3.frequency = 0.028
	var img := Image.create(SAND_TEXELS, SAND_TEXELS, false, Image.FORMAT_RGB8)
	for y in SAND_TEXELS:
		for x in SAND_TEXELS:
			var v := n.get_noise_2d(x, y) * 0.7 + n2.get_noise_2d(x, y) * 0.3
			var c := SAND.lerp(SAND_SALT if v > 0.0 else SAND_CLAY, clampf(absf(v) * 1.6, 0.0, 0.75))
			var w := n3.get_noise_2d(x, y)
			if w > POOL_EDGE:
				c = c.lerp(SAND_WET, clampf((w - POOL_EDGE) * 5.0, 0.0, 0.7))
			if w > POOL_CORE:
				c = c.lerp(SAND_POOL, clampf((w - POOL_CORE) * 6.0, 0.0, 0.8))
''')
open(p,'w',encoding='utf-8').write(s)
EOF
git diff --stat view/style_showcase.gd

